package com.nigson.acceptance.carrier;
import com.nigson.acceptance.fulfillment.ShipmentFixture;
import com.nigson.commerce.fulfillment.*;
import com.nigson.shared.security.PrivateWorkload;
import com.nigson.shared.events.EventCodec;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import org.junit.jupiter.api.*;
import java.util.*;
import static org.assertj.core.api.Assertions.*;
class CarrierContextPersistenceTest {
 ShipmentFixture f;CarrierContextService service;
 @BeforeEach void setup(){String url=System.getenv("NIGSON_TEST_JDBC_URL");Assumptions.assumeTrue(url!=null,"carrier-check supplies isolated PostgreSQL");if(!url.matches("jdbc:postgresql://127.0.0.1:[0-9]+/nigson"))throw new IllegalArgumentException("LOCAL_TEST_DB_REQUIRED");var ds=new DriverManagerDataSource(url+"?currentSchema=commerce","nigson_commerce_app","mock-commerce-runtime");var manager=new DataSourceTransactionManager(ds);var jdbc=new JdbcTemplate(ds);f=new ShipmentFixture(jdbc,manager);service=new CarrierContextService(f.repository,jdbc,manager);}
 @AfterEach void cleanup(){if(f!=null)f.close();}
 static PrivateWorkload.Proof proof(){return new PrivateWorkload.Proof("nigson-integration","synthetic-context",PrivateWorkload.ROUTES.stream().filter(r->r.api().equals("API-119")).findFirst().orElseThrow(),null);}
 public static void freeze(ShipmentFixture f){var origin=EventCodec.JSON.readTree("{\"recipient\":\"Synthetic frozen origin\",\"phone\":\"+2348000000001\",\"line1\":\"Synthetic origin\",\"line2\":null,\"city\":\"Lagos\",\"region\":\"LA\",\"postalCode\":null,\"countryCode\":\"NG\"}");f.inventory.jdbc.update("UPDATE commerce.sales_order SET carrier_snapshot=jsonb_set(carrier_snapshot,'{providerSnapshot}',?::jsonb),address_snapshot=address_snapshot||?::jsonb WHERE id=?",EventCodec.JSON.writeValueAsString(Map.of("shipper",origin)),"{\"label\":\"Synthetic immutable address\",\"line2\":null,\"postalCode\":null,\"isDefault\":false}",f.order);}
 @Test void scopedContextUsesFrozenPaidOrderAndStablePackingWithoutSideEffects(){freeze(f);var shipment=f.create("5","FEDEX",null,"context");var context=service.context(proof(),shipment.id());assertThat(context.shipper().recipient()).isEqualTo("Synthetic frozen origin");assertThat(context.packages()).hasSize(1);assertThat(context.packages().getFirst().quantity()).isEqualTo("5");assertThat(context.mode()).isEqualTo("MOCK");assertThat(context.bookingReference()).isEqualTo(f.inventory.jdbc.queryForObject("SELECT booking_request_id::text FROM commerce.shipment WHERE id=?",String.class,shipment.id()));assertThat(context.toString()).doesNotContain("origin","2348");assertThat(EventCodec.JSON.valueToTree(context).propertyNames()).containsExactlyInAnyOrder("shipmentId","orderId","address","shipper","serviceCode","packages","bookingReference","mode");assertThat(EventCodec.JSON.valueToTree(context.address()).propertyNames()).doesNotContain("id","version","organizationId");assertThat(service.context(proof(),shipment.id())).isEqualTo(context);assertThat(f.value("on_hand")).isEqualByComparingTo("10");assertThat(f.value("allocated")).isEqualByComparingTo("5");assertThat(f.inventory.jdbc.queryForObject("SELECT version FROM commerce.shipment WHERE id=?",Long.class,shipment.id())).isZero();}
 @Test void missingOriginAndUnverifiedSettlementFailClosed(){var shipment=f.create("5","FEDEX",null,"context");assertThatThrownBy(()->service.context(proof(),shipment.id())).hasMessage("FULFILLMENT_RULE_VIOLATION");freeze(f);assertThat(service.context(proof(),shipment.id())).isNotNull();f.inventory.jdbc.update("UPDATE commerce.payment_attempt SET verified_at=NULL WHERE order_id=?",f.order);assertThatThrownBy(()->service.context(proof(),shipment.id())).hasMessage("FULFILLMENT_RULE_VIOLATION");}
 @Test void wrongScopeClientOrSignedActorCannotReadContext(){freeze(f);var shipment=f.create("5","FEDEX",null,"context");var p=proof();for(var bad:List.of(new PrivateWorkload.Proof("nigson-experience",p.subject(),p.route(),null),new PrivateWorkload.Proof(p.client(),p.subject(),PrivateWorkload.ROUTES.stream().filter(r->r.api().equals("API-120")).findFirst().orElseThrow(),null),new PrivateWorkload.Proof(p.client(),p.subject(),p.route(),f.inventory.actor)))assertThatThrownBy(()->service.context(bad,shipment.id())).hasMessage("ACCESS_DENIED");assertThat(p.route().phase()).isEqualTo(1);}
}
